#[derive(Default, PartialEq, Debug, Clone)]
pub struct Modify {
    pub col: String,
    pub previous: Option<ValueInstance>,
    pub row: GenericId,
    pub value: ValueInstance,
}

impl Modify {
    pub fn serialize_to<'a>(&self, builder: &mut flatbuffers::FlatBufferBuilder<'a>) -> flatbuffers::WIPOffset<FbsModify<'a>> {
        use crate::types::generated::table_generated::ModifyBuilder as FbsModifyBuilder;

        let col_offset = builder.create_string(&self.col);
        let previous_offset = self.previous.as_ref().map(|o| o.serialize_to(builder));
        let row_offset = self.row.serialize_to(builder);
        let value_offset = self.value.serialize_to(builder);

        let mut bldr = FbsModifyBuilder::new(builder);
        bldr.add_col(col_offset);
        if let Some(offset) = previous_offset {
            bldr.add_previous(offset);
        }
        bldr.add_row(row_offset);
        bldr.add_value(value_offset);
        bldr.finish()
    }
}

impl From<FbsModify<'_>> for Modify {
    fn from(fbs: FbsModify<'_>) -> Self {
        let col = fbs.col().to_owned();
        let previous = fbs.previous().map(ValueInstance::from);
        let row = GenericId::from(fbs.row());
        let value = ValueInstance::from(fbs.value());
        Self {
            col,
            previous,
            row,
            value,
        }
    }
}

impl TryFrom<&[u8]> for Modify {
    type Error = flatbuffers::InvalidFlatbuffer;
    fn try_from(bytes: &[u8]) -> Result<Self, Self::Error> {
        let fbs = flatbuffers::size_prefixed_root::<FbsModify>(bytes)?;
        Ok(Self::from(fbs))
    }
}

impl From<Modify> for Vec<u8> {
    fn from(obj: Modify) -> Self {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = obj.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }
}

