#[derive(Clone, Debug, PartialEq)]
pub enum ChangeOp {
    Modify(Modify),
    Delete(Delete),
    Restore(Restore),
}

impl Default for ChangeOp {
    fn default() -> Self {
        Self::Modify(Modify::default())
    }
}

impl ChangeOp {
    pub fn serialize_to(&self, builder: &mut flatbuffers::FlatBufferBuilder) -> (WIPOffset<UnionWIPOffset>, FbsChangeOp) {
        match self {
            Self::Modify(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsChangeOp::Modify;
                (offset, ty)
            }
            Self::Delete(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsChangeOp::Delete;
                (offset, ty)
            }
            Self::Restore(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsChangeOp::Restore;
                (offset, ty)
            }
        }
    }
}

