/// A DiffStream encodes a sequence of operations that should be performed on a table.
/// The operations are applied in order to the table, i.e. the ordering of the `seq` field is significant.
#[derive(Default, PartialEq, Debug, Clone)]
pub struct DiffStream {
    /// We can optionally associate attributes with the diffstream.
    /// When the change history of the table is retrieved, the attributes from the diffstream
    /// will be accessible as the `attributes` field on the ChangeSet associated with this diffstream.
    pub attributes: Option<Vec<Attr>>,
    /// This is the head revision of the directory object that contains the table.
    pub base: ContentId,
    pub seq: Vec<OpEntry>,
}

impl DiffStream {
    pub fn serialize_to<'a>(&self, builder: &mut flatbuffers::FlatBufferBuilder<'a>) -> flatbuffers::WIPOffset<FbsDiffStream<'a>> {
        use crate::types::generated::table_generated::DiffStreamBuilder as FbsDiffStreamBuilder;

        let attributes_offset = self.attributes.as_ref().map(|v| {
            let mut attributes_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                attributes_offsets.push(offset);
            }
            let attributes_offset = builder.create_vector(&attributes_offsets);
            attributes_offset
        });
        let base_offset = self.base.serialize_to(builder);
        let mut seq_offsets = Vec::with_capacity(self.seq.len());
        for val in self.seq.iter() {
            let offset = val.serialize_to(builder);
            seq_offsets.push(offset);
        }
        let seq_offset = builder.create_vector(&seq_offsets);

        let mut bldr = FbsDiffStreamBuilder::new(builder);
        if let Some(offset) = attributes_offset {
            bldr.add_attributes(offset);
        }
        bldr.add_base(base_offset);
        bldr.add_seq(seq_offset);
        bldr.finish()
    }
}

impl From<FbsDiffStream<'_>> for DiffStream {
    fn from(fbs: FbsDiffStream<'_>) -> Self {
        let attributes = if let Some(val) = fbs.attributes() {
            let mut attributes = Vec::new();
            for elem in val {
                attributes.push(elem.into());
            }

            Some(attributes)
        } else {
            None
        };

        let base = ContentId::from(fbs.base());
        let mut seq = Vec::new();
        for elem in fbs.seq() {
            seq.push(elem.into());
        }

        Self {
            attributes,
            base,
            seq,
        }
    }
}

impl TryFrom<&[u8]> for DiffStream {
    type Error = flatbuffers::InvalidFlatbuffer;
    fn try_from(bytes: &[u8]) -> Result<Self, Self::Error> {
        let fbs = flatbuffers::size_prefixed_root::<FbsDiffStream>(bytes)?;
        Ok(Self::from(fbs))
    }
}

impl From<DiffStream> for Vec<u8> {
    fn from(obj: DiffStream) -> Self {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = obj.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }
}

